export const DB_PROTOCOL_VERSION = 1 as const;

export type DbValue = string | number | boolean | null | bigint | Uint8Array | Int8Array | ArrayBuffer;
export type DbParams = readonly DbValue[] | Readonly<Record<string, DbValue>>;
export type DbRow = Readonly<Record<string, DbValue>>;

export type EngineMode = 'opfs-sahpool' | 'indexeddb-snapshot' | 'memory';
/** `recent` = 输入里没有可用检索词，按固定/重要度/时间取最近的候选，而不是拿整句去做子串匹配。 */
export type SearchMode = 'fts5' | 'like' | 'recent';

export interface EngineStatus {
  readonly mode: EngineMode;
  readonly persistent: boolean;
  readonly sqliteVersion: string;
  readonly fts5: boolean;
  readonly snapshotAvailable: boolean;
  readonly warning?: string;
}

export interface DbStatement {
  readonly sql: string;
  readonly params?: DbParams;
}

export interface OpenPayload {
  readonly filename?: string;
}

export interface ExecutePayload extends DbStatement {}

export interface TransactionPayload {
  readonly statements: readonly DbStatement[];
}

export interface SearchPayload {
  readonly scopeId: string;
  readonly query: string;
  readonly limit?: number;
}

export type EmptyPayload = Readonly<Record<string, never>>;

export interface ExecuteResult {
  readonly rows: readonly DbRow[];
  /** 本条 INSERT/UPDATE/DELETE 改动的行数；只读语句固定为 0，不沿用连接上一次写入的值。 */
  readonly changes: number;
  readonly lastInsertRowId: bigint;
}

export interface SearchRow extends DbRow {
  readonly id: number;
  readonly scope_id: string;
  readonly kind: string;
  readonly sheet_id: string | null;
  readonly row_key: string | null;
  readonly text: string;
  readonly importance: number;
  readonly pinned: number;
  readonly valid_from: number | null;
  readonly valid_to: number | null;
  readonly tokens: number;
  readonly hash: string;
  readonly updated_at: number;
  readonly fts_score: number;
}

export interface SearchResult {
  readonly rows: readonly SearchRow[];
  readonly mode: SearchMode;
  readonly queryLength: number;
}

export interface ExportResult {
  readonly data: Uint8Array;
  readonly filename: string;
  readonly mimeType: 'application/x-sqlite3';
}

export interface DbRequestPayloadMap {
  readonly open: OpenPayload;
  readonly execute: ExecutePayload;
  readonly transaction: TransactionPayload;
  readonly search: SearchPayload;
  readonly export: EmptyPayload;
  readonly status: EmptyPayload;
  readonly close: EmptyPayload;
}

export interface DbResponsePayloadMap {
  readonly open: EngineStatus;
  readonly execute: ExecuteResult;
  readonly transaction: readonly ExecuteResult[];
  readonly search: SearchResult;
  readonly export: ExportResult;
  readonly status: EngineStatus;
  readonly close: EmptyPayload;
}

export type DbRequestKind = keyof DbRequestPayloadMap;
export type DbResponseKind = keyof DbResponsePayloadMap;

export type DbRequest<K extends DbRequestKind = DbRequestKind> = {
  readonly version: typeof DB_PROTOCOL_VERSION;
  readonly id: string;
  readonly kind: K;
  readonly payload: DbRequestPayloadMap[K];
};

export type DbRequestEnvelope = { [K in DbRequestKind]: DbRequest<K> }[DbRequestKind];

export type DbSuccessResponse<K extends DbResponseKind = DbResponseKind> = {
  readonly version: typeof DB_PROTOCOL_VERSION;
  readonly id: string;
  readonly ok: true;
  readonly kind: K;
  readonly payload: DbResponsePayloadMap[K];
};

export type DbErrorCode =
  | 'engine-unavailable'
  | 'sql-error'
  | 'snapshot-corrupt'
  | 'protocol-error'
  | 'timeout'
  | 'closed';

export interface DbErrorPayload {
  readonly code: DbErrorCode;
  readonly message: string;
  readonly sqliteCode?: number;
}

export type DbErrorResponse = {
  readonly version: typeof DB_PROTOCOL_VERSION;
  readonly id: string;
  readonly ok: false;
  readonly error: DbErrorPayload;
};

export type DbResponse = DbSuccessResponse | DbErrorResponse;

export function isDbValue(value: unknown): value is DbValue {
  return (
    value === null ||
    typeof value === 'string' ||
    typeof value === 'number' ||
    typeof value === 'boolean' ||
    typeof value === 'bigint' ||
    value instanceof Uint8Array ||
    value instanceof Int8Array ||
    value instanceof ArrayBuffer
  );
}

export function isDbParams(value: unknown): value is DbParams {
  if (Array.isArray(value)) return value.every(isDbValue);
  if (!isRecord(value)) return false;
  return Object.values(value).every(isDbValue);
}

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

const REQUEST_KINDS: readonly DbRequestKind[] = ['open', 'execute', 'transaction', 'search', 'export', 'status', 'close'];

export function isDbRequest(value: unknown): value is DbRequestEnvelope {
  if (!isRecord(value)) return false;
  return (
    value.version === DB_PROTOCOL_VERSION &&
    typeof value.id === 'string' &&
    value.id.length > 0 &&
    typeof value.kind === 'string' &&
    REQUEST_KINDS.includes(value.kind as DbRequestKind) &&
    isRecord(value.payload)
  );
}

export function isDbResponse(value: unknown): value is DbResponse {
  if (!isRecord(value)) return false;
  if (value.version !== DB_PROTOCOL_VERSION || typeof value.id !== 'string' || typeof value.ok !== 'boolean') return false;
  if (value.ok) return typeof value.kind === 'string' && isRecord(value.payload);
  return isRecord(value.error) && typeof value.error.code === 'string' && typeof value.error.message === 'string';
}

export function createRequest<K extends DbRequestKind>(id: string, kind: K, payload: DbRequestPayloadMap[K]): DbRequest<K> {
  return { version: DB_PROTOCOL_VERSION, id, kind, payload };
}

export function createSuccessResponse<K extends DbResponseKind>(
  id: string,
  kind: K,
  payload: DbResponsePayloadMap[K],
): DbSuccessResponse<K> {
  return { version: DB_PROTOCOL_VERSION, id, ok: true, kind, payload };
}

export function createErrorResponse(id: string, error: DbErrorPayload): DbErrorResponse {
  return { version: DB_PROTOCOL_VERSION, id, ok: false, error };
}

/**
 * 主线程可见的数据库访问面。
 * Worker 客户端是生产实现；测试与降级路径可以提供同形状的进程内实现。
 */
export interface SqliteGateway {
  open(): Promise<EngineStatus>;
  status(): Promise<EngineStatus>;
  execute(statement: DbStatement): Promise<ExecuteResult>;
  transaction(statements: readonly DbStatement[]): Promise<readonly ExecuteResult[]>;
  search(scopeId: string, query: string, limit?: number): Promise<SearchResult>;
  exportDatabase(): Promise<ExportResult>;
  close(): Promise<void>;
}