/**
 * 检索词构造：把一段自然语言输入拆成可用于 FTS5 trigram 与 LIKE 的检索词。
 *
 * 为什么必须切词：`mem_fts` 用 `tokenize='trigram'`，把整句包成一个 FTS 短语等价于
 * 「整句必须作为子串出现在某一行里」，真实用户输入几乎永远命中 0 条；LIKE 回退同理。
 * 切成短词后按 OR 检索，才是「相关就召回」的语义。
 *
 * 独立成模块的原因：worker 侧执行 SQL、主线程侧记录检索模式与诊断，两边必须共用同一套规则，
 * 否则日志里的模式与真实命中集合会对不上。这里是纯函数，不触碰数据库。
 */

/** trigram 索引下的最小可匹配长度：短于 3 个字符的词在 FTS 里永远匹配不到。 */
export const FTS_MIN_TERM_LENGTH = 3;

const MAX_TERMS = 32;
const MAX_TERM_LENGTH = 12;
const CJK_GRAM_SIZE = 3;
/** 短片段穷举 3-gram；再长就隔字取，避免一个长句吃掉全部词位。 */
const CJK_DENSE_GRAM_LIMIT = 8;
const CJK_SPARSE_GRAM_STEP = 2;
const MIN_ASCII_TERM_LENGTH = 2;

/**
 * 续写指令类停用词：这些输入不表达检索意图。
 * 不排除的话，「继续」会被当成关键词去做子串匹配，命中的是正文里恰好出现过"继续"的行；
 * 排除后整句切不出词，检索退化成"最近的表行"，这才是续写时真正想要的上下文。
 */
const STOP_TERMS: ReadonlySet<string> = new Set([
  '继续', '接着', '然后', '下一', '再来', '开始', '好的', '嗯嗯',
  'continue', 'next', 'go', 'ok', 'okay',
]);

const CJK_PATTERN = /[\u3400-\u4dbf\u4e00-\u9fff\u3040-\u30ff\uac00-\ud7af]/;
const WORD_CHARS = /[\p{L}\p{N}]+/gu;

/**
 * 剥掉结构化包裹再切词：注入区块、story_context、HTML 注释与代码围栏都是提示词脚手架，
 * 它们的标签名会在每一轮里重复出现，当成检索词只会把所有行都召回。
 */
function stripScaffolding(raw: string): string {
  return raw
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/```[\s\S]*?```/g, ' ')
    .replace(/<\/?[A-Za-z_][\w:-]*(?:\s[^>]*)?>/g, ' ')
    .replace(/【[^】]*】/g, ' ');
}

function isCjk(value: string): boolean {
  return CJK_PATTERN.test(value);
}

/**
 * 中文片段切词。
 *
 * 不能整段保留：trigram 索引下一个词就是一个短语，`"雨伞在哪"` 要求这四个字连续出现，
 * 而库里存的是"雨夜借走了蓝色雨伞"，整段匹配必然落空。切成 3-gram 后按 OR 检索才能命中。
 */
function expandCjkChunk(chunk: string): readonly string[] {
  if (chunk.length <= CJK_GRAM_SIZE) return [chunk];
  const step = chunk.length <= CJK_DENSE_GRAM_LIMIT ? 1 : CJK_SPARSE_GRAM_STEP;
  const grams: string[] = [];
  for (let index = 0; index + CJK_GRAM_SIZE <= chunk.length; index += step) {
    grams.push(chunk.slice(index, index + CJK_GRAM_SIZE));
  }
  const tail = chunk.slice(-CJK_GRAM_SIZE);
  if (grams[grams.length - 1] !== tail) grams.push(tail);
  return grams;
}

/** 同一个字重复填满的 gram（「啊啊啊」「。。。」）没有区分度，直接丢掉。 */
function isDegenerate(term: string): boolean {
  return new Set(term).size <= 1;
}

/**
 * 把自然语言输入拆成检索词：ASCII 词按词切，中文按短语或重叠 gram 切。
 * 返回顺序与出现顺序一致，超出上限时保留靠前的部分（主体、人名、地点通常出现在前面）。
 */
export function buildSearchTerms(raw: string): readonly string[] {
  const source = stripScaffolding(String(raw ?? ''));
  const terms: string[] = [];
  const seen = new Set<string>();
  const push = (value: string): void => {
    const term = value.slice(0, MAX_TERM_LENGTH);
    if (!term || isDegenerate(term) || STOP_TERMS.has(term) || seen.has(term)) return;
    seen.add(term);
    terms.push(term);
  };

  for (const match of source.matchAll(WORD_CHARS)) {
    if (terms.length >= MAX_TERMS) break;
    const word = match[0];
    if (!isCjk(word)) {
      if (word.length >= MIN_ASCII_TERM_LENGTH) push(word.toLowerCase());
      continue;
    }
    if (STOP_TERMS.has(word)) continue;
    for (const chunk of expandCjkChunk(word)) {
      if (terms.length >= MAX_TERMS) break;
      push(chunk);
    }
  }
  return terms.slice(0, MAX_TERMS);
}

/** FTS5 可用的检索词：短于 trigram 长度的词交给 LIKE 处理。 */
export function ftsSearchTerms(terms: readonly string[]): readonly string[] {
  return terms.filter((term) => term.length >= FTS_MIN_TERM_LENGTH);
}

/** 多词 OR 的 FTS5 表达式；每个词自身仍是短语，避免 trigram 把词内顺序打散。 */
export function toFtsMatchExpression(terms: readonly string[]): string {
  return terms.map((term) => `"${term.replaceAll('"', '""')}"`).join(' OR ');
}