import type {
  BindableValue,
  Database,
  Sqlite3Static,
  SqlValue,
  WasmPointer,
} from '@sqlite.org/sqlite-wasm';
import type {
  DbParams,
  DbRow,
  DbStatement,
  DbValue,
  EngineMode,
  EngineStatus,
  ExecuteResult,
  SearchMode,
  SearchResult,
  SearchRow,
} from '../protocol.js';
import { migrateSchema } from './schema.js';
import { buildSearchTerms, ftsSearchTerms, toFtsMatchExpression } from '../search-query.js';

const DEFAULT_FILENAME = 'phone-memory.sqlite3';
const SNAPSHOT_DATABASE = 'narrative-phone-sqlite';
const SNAPSHOT_STORE = 'snapshots';
const SNAPSHOT_KEY = 'main';

type BindingParams = readonly BindableValue[] | Readonly<Record<string, BindableValue>>;

type RuntimeInit = () => Promise<Sqlite3Static>;

export interface SnapshotStore {
  readonly available: boolean;
  load(): Promise<Uint8Array | null>;
  save(data: Uint8Array): Promise<void>;
}

export interface SqliteLoader {
  (): Promise<Sqlite3Static>;
}

export interface DatabaseEngineOptions {
  readonly filename?: string;
  readonly loadSqlite?: SqliteLoader;
  readonly snapshotStore?: SnapshotStore;
  readonly opfsDirectory?: string;
}

export class DatabaseEngineError extends Error {
  readonly code: 'engine-unavailable' | 'sql-error' | 'snapshot-corrupt';
  readonly sqliteCode?: number;

  constructor(
    code: 'engine-unavailable' | 'sql-error' | 'snapshot-corrupt',
    message: string,
    sqliteCode?: number,
  ) {
    super(message);
    this.name = 'DatabaseEngineError';
    this.code = code;
    this.sqliteCode = sqliteCode;
  }
}

export class IndexedDbSnapshotStore implements SnapshotStore {
  readonly available = typeof indexedDB !== 'undefined';

  readonly #databaseName: string;

  constructor(databaseName = SNAPSHOT_DATABASE) {
    this.#databaseName = databaseName;
  }

  async load(): Promise<Uint8Array | null> {
    if (!this.available) return null;
    const database = await this.#open();
    try {
      return await new Promise<Uint8Array | null>((resolve, reject) => {
        const transaction = database.transaction(SNAPSHOT_STORE, 'readonly');
        const request = transaction.objectStore(SNAPSHOT_STORE).get(SNAPSHOT_KEY);
        request.onsuccess = () => {
          const value: unknown = request.result;
          if (value instanceof Uint8Array) {
            resolve(new Uint8Array(value));
          } else if (value instanceof ArrayBuffer) {
            resolve(new Uint8Array(value.slice(0)));
          } else {
            resolve(null);
          }
        };
        request.onerror = () => reject(request.error ?? new Error('无法读取 IndexedDB SQLite 快照'));
      });
    } finally {
      database.close();
    }
  }

  async save(data: Uint8Array): Promise<void> {
    if (!this.available) return;
    const database = await this.#open();
    try {
      await new Promise<void>((resolve, reject) => {
        const transaction = database.transaction(SNAPSHOT_STORE, 'readwrite');
        transaction.objectStore(SNAPSHOT_STORE).put(new Uint8Array(data), SNAPSHOT_KEY);
        transaction.oncomplete = () => resolve();
        transaction.onerror = () => reject(transaction.error ?? new Error('无法写入 IndexedDB SQLite 快照'));
        transaction.onabort = () => reject(transaction.error ?? new Error('IndexedDB SQLite 快照事务已中止'));
      });
    } finally {
      database.close();
    }
  }

  #open(): Promise<IDBDatabase> {
    return new Promise<IDBDatabase>((resolve, reject) => {
      const request = indexedDB.open(this.#databaseName, 1);
      request.onupgradeneeded = () => {
        request.result.createObjectStore(SNAPSHOT_STORE);
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error ?? new Error('无法打开 SQLite 快照数据库'));
      request.onblocked = () => reject(new Error('SQLite 快照数据库被其他连接阻塞'));
    });
  }
}

function defaultSnapshotStore(): SnapshotStore | undefined {
  return typeof indexedDB === 'undefined' ? undefined : new IndexedDbSnapshotStore();
}

async function loadBrowserSqlite(): Promise<Sqlite3Static> {
  const loaded: unknown = await import(new URL('./sqlite/index.mjs', import.meta.url).href);
  if (!isRecord(loaded) || typeof loaded.default !== 'function') {
    throw new DatabaseEngineError('engine-unavailable', 'SQLite WASM 浏览器入口缺少默认初始化函数');
  }
  const initializer = loaded.default;
  if (!isRuntimeInit(initializer)) {
    throw new DatabaseEngineError('engine-unavailable', 'SQLite WASM 初始化函数类型不匹配');
  }
  return initializer();
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function isRuntimeInit(value: unknown): value is RuntimeInit {
  return typeof value === 'function';
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/**
 * OPFS 与 File System Access API 都是 secure-context-only：
 * 在 `http://` 非 localhost 站点上，浏览器压根不暴露 `navigator.storage` 与 `FileSystemFileHandle`，
 * sqlite-wasm 的能力探测因此直接抛 "Missing required OPFS APIs."。
 * 这不是 SQLite 或本扩展的故障，所以要把可操作的根因写进状态行，而不是把英文原文丢给用户。
 */
function opfsFailureReason(error: unknown): string {
  const detail = errorMessage(error);
  if (globalThis.isSecureContext !== false) return detail;
  const origin = globalThis.location?.origin ?? '当前地址';
  return `${origin} 不是安全上下文（非 HTTPS 且非 localhost），浏览器不提供 OPFS 接口；`
    + `改用 HTTPS 访问即可恢复 OPFS 持久化。原始报错：${detail}`;
}

function toBindingParams(params: DbParams | undefined): BindingParams | undefined {
  return params;
}

function isMutation(sql: string): boolean {
  return /^(?:INSERT|UPDATE|DELETE|REPLACE|CREATE|ALTER|DROP|VACUUM|REINDEX|PRAGMA\s+[^=]+\s*=)/i.test(sql.trim());
}

/**
 * `sqlite3_changes()` 只在 INSERT/UPDATE/DELETE 后更新，SELECT 会沿用上一条写入的值。
 * 直接上报会让只读查询看起来"影响了 N 行"，因此非写语句一律记 0。
 */
function changesOf(database: Database, sql: string): number {
  return /^(?:INSERT|UPDATE|DELETE|REPLACE)\b/i.test(sql.trim()) ? Number(database.changes(false)) : 0;
}

function toNumber(value: SqlValue | DbValue | undefined): number {
  return typeof value === 'number' ? value : Number(value ?? 0);
}

function normalizeRows(rows: readonly Record<string, SqlValue>[]): readonly DbRow[] {
  return rows.map((row) => row);
}

function escapeLike(value: string): string {
  return value.replaceAll('\\', '\\\\').replaceAll('%', '\\%').replaceAll('_', '\\_');
}

function normalizeSearchRow(row: DbRow): SearchRow {
  return {
    ...row,
    id: toNumber(row.id),
    scope_id: String(row.scope_id ?? ''),
    kind: String(row.kind ?? ''),
    sheet_id: typeof row.sheet_id === 'string' ? row.sheet_id : null,
    row_key: typeof row.row_key === 'string' ? row.row_key : null,
    text: String(row.text ?? ''),
    importance: toNumber(row.importance),
    pinned: toNumber(row.pinned),
    valid_from: typeof row.valid_from === 'number' ? row.valid_from : null,
    valid_to: typeof row.valid_to === 'number' ? row.valid_to : null,
    tokens: toNumber(row.tokens),
    hash: String(row.hash ?? ''),
    updated_at: toNumber(row.updated_at),
    fts_score: toNumber(row.fts_score),
  };
}

export class DatabaseEngine {
  readonly #options: DatabaseEngineOptions;
  readonly #filename: string;
  readonly #snapshotStore: SnapshotStore | undefined;
  #sqlite3: Sqlite3Static | null = null;
  #database: Database | null = null;
  #mode: EngineMode | null = null;
  #status: EngineStatus | null = null;
  #snapshotWarning: string | undefined;

  constructor(options: DatabaseEngineOptions = {}) {
    this.#options = options;
    this.#filename = options.filename ?? DEFAULT_FILENAME;
    this.#snapshotStore = options.snapshotStore ?? defaultSnapshotStore();
  }

  async open(): Promise<EngineStatus> {
    if (this.#status) return this.#status;

    let sqlite3: Sqlite3Static;
    try {
      sqlite3 = await (this.#options.loadSqlite ?? loadBrowserSqlite)();
    } catch (error) {
      if (error instanceof DatabaseEngineError) throw error;
      throw new DatabaseEngineError('engine-unavailable', `SQLite WASM 初始化失败：${errorMessage(error)}`);
    }
    this.#sqlite3 = sqlite3;

    let persistent = false;
    try {
      if (typeof sqlite3.installOpfsSAHPoolVfs === 'function') {
        const pool = await sqlite3.installOpfsSAHPoolVfs({
          directory: this.#options.opfsDirectory ?? '/narrative-phone',
          initialCapacity: 4,
        });
        this.#database = new pool.OpfsSAHPoolDb(this.#filename);
        this.#mode = 'opfs-sahpool';
        persistent = true;
      }
    } catch (error) {
      this.#database = null;
      this.#mode = null;
      this.#snapshotWarning = `OPFS SAH pool 不可用，已降级：${opfsFailureReason(error)}`;
    }

    if (!this.#database) {
      try {
        this.#database = new sqlite3.oo1.DB(':memory:');
        this.#mode = this.#snapshotStore?.available ? 'indexeddb-snapshot' : 'memory';
        persistent = this.#mode === 'indexeddb-snapshot';
        if (this.#mode === 'indexeddb-snapshot') await this.#restoreSnapshot();
      } catch (error) {
        this.#database?.close();
        this.#database = null;
        throw new DatabaseEngineError('engine-unavailable', `SQLite 内存库初始化失败：${errorMessage(error)}`);
      }
    }

    try {
      const migration = migrateSchema(this.#database);
      if (this.#mode === 'indexeddb-snapshot') await this.#saveSnapshot();
      this.#status = {
        mode: this.#mode ?? 'memory',
        persistent,
        sqliteVersion: sqlite3.version.libVersion,
        fts5: migration.fts5,
        snapshotAvailable: this.#snapshotStore?.available ?? false,
        ...(this.#snapshotWarning ? { warning: this.#snapshotWarning } : {}),
      };
      return this.#status;
    } catch (error) {
      this.#database?.close();
      this.#database = null;
      throw new DatabaseEngineError('engine-unavailable', `数据库 schema 初始化失败：${errorMessage(error)}`);
    }
  }

  status(): EngineStatus {
    if (!this.#status) throw new DatabaseEngineError('engine-unavailable', '数据库尚未打开');
    return this.#status;
  }

  execute(statement: DbStatement): ExecuteResult {
    const database = this.#requireDatabase();
    try {
      const rows = database.exec({
        sql: statement.sql,
        ...(toBindingParams(statement.params) ? { bind: toBindingParams(statement.params) } : {}),
        rowMode: 'object',
        returnValue: 'resultRows',
      });
      const result: ExecuteResult = {
        rows: normalizeRows(rows),
        changes: changesOf(database, statement.sql),
        lastInsertRowId: this.#lastInsertRowId(database),
      };
      if (isMutation(statement.sql) && this.#mode === 'indexeddb-snapshot') void this.#saveSnapshot();
      return result;
    } catch (error) {
      throw this.#toSqlError(error);
    }
  }

  async transaction(statements: readonly DbStatement[]): Promise<readonly ExecuteResult[]> {
    const database = this.#requireDatabase();
    const results: ExecuteResult[] = [];
    try {
      database.exec('BEGIN IMMEDIATE');
      for (const statement of statements) {
        results.push(this.#executeWithoutSnapshot(statement));
      }
      database.exec('COMMIT');
      if (this.#mode === 'indexeddb-snapshot') await this.#saveSnapshot();
      return results;
    } catch (error) {
      try {
        database.exec('ROLLBACK');
      } catch {
        // Preserve the statement error; the connection remains owned by the worker.
      }
      throw this.#toSqlError(error);
    }
  }

  /**
   * 自动注入候选检索。
   *
   * 候选集刻意收窄成「非 manual 表的行」：
   * - `sheet_id IS NOT NULL` 排除记忆库条目投影。记忆库有自己的编号选取与独立注入区块，
   *   数据中心再模糊召回同一批内容只会在同一个请求里重复注入整段正文。
   * - `policy <> 'manual'` 让「仅手动查询，不自动注入」这条策略真正生效。
   *
   * 检索词由 `buildSearchTerms` 切出后按 OR 匹配；一个词都切不出来时退化为「最近候选」，
   * 而不是拿整句去做子串匹配（trigram 短语与 LIKE 都会因此几乎永不命中）。
   */
  search(scopeId: string, query: string, limit = 20): SearchResult {
    const database = this.#requireDatabase();
    const boundedLimit = Math.max(1, Math.min(100, Math.trunc(limit)));
    const terms = buildSearchTerms(query);
    const ftsTerms = ftsSearchTerms(terms);
    const mode: SearchMode = this.status().fts5 && ftsTerms.length > 0
      ? 'fts5'
      : terms.length > 0 ? 'like' : 'recent';
    const rows = mode === 'fts5'
      ? database.exec({
          sql: `
            SELECT d.*, bm25(mem_fts) AS fts_score
            FROM mem_fts
            JOIN mem_doc AS d ON d.id = mem_fts.rowid
            JOIN sheet AS s ON s.id = d.sheet_id
            WHERE d.scope_id = ? AND s.policy <> 'manual' AND mem_fts MATCH ?
            ORDER BY bm25(mem_fts), d.pinned DESC, d.importance DESC, d.updated_at DESC
            LIMIT ?
          `,
          bind: [scopeId, toFtsMatchExpression(ftsTerms), boundedLimit],
          rowMode: 'object',
          returnValue: 'resultRows',
        })
      : mode === 'like'
        ? database.exec({
            sql: `
              SELECT d.*, 0.0 AS fts_score
              FROM mem_doc AS d
              JOIN sheet AS s ON s.id = d.sheet_id
              WHERE d.scope_id = ? AND s.policy <> 'manual'
                AND (${terms.map(() => "d.text LIKE ? ESCAPE '\\'").join(' OR ')})
              ORDER BY d.pinned DESC, d.importance DESC, d.updated_at DESC
              LIMIT ?
            `,
            bind: [scopeId, ...terms.map((term) => `%${escapeLike(term)}%`), boundedLimit],
            rowMode: 'object',
            returnValue: 'resultRows',
          })
        : database.exec({
            sql: `
              SELECT d.*, 0.0 AS fts_score
              FROM mem_doc AS d
              JOIN sheet AS s ON s.id = d.sheet_id
              WHERE d.scope_id = ? AND s.policy <> 'manual'
              ORDER BY d.pinned DESC, d.importance DESC, d.updated_at DESC, d.id DESC
              LIMIT ?
            `,
            bind: [scopeId, boundedLimit],
            rowMode: 'object',
            returnValue: 'resultRows',
          });
    return {
      rows: normalizeRows(rows).map(normalizeSearchRow),
      mode,
      queryLength: query.trim().length,
    } satisfies SearchResult;
  }

  exportDatabase(): Uint8Array {
    const database = this.#requireDatabase();
    const sqlite3 = this.#sqlite3;
    if (!sqlite3 || database.pointer === undefined) {
      throw new DatabaseEngineError('engine-unavailable', 'SQLite 导出时数据库句柄不可用');
    }
    try {
      return sqlite3.capi.sqlite3_js_db_export(database.pointer);
    } catch (error) {
      throw new DatabaseEngineError('engine-unavailable', `SQLite 导出失败：${errorMessage(error)}`);
    }
  }

  async close(): Promise<void> {
    if (this.#database && this.#mode === 'indexeddb-snapshot') await this.#saveSnapshot();
    this.#database?.close();
    this.#database = null;
    this.#status = null;
  }

  #executeWithoutSnapshot(statement: DbStatement): ExecuteResult {
    const database = this.#requireDatabase();
    const rows = database.exec({
      sql: statement.sql,
      ...(toBindingParams(statement.params) ? { bind: toBindingParams(statement.params) } : {}),
      rowMode: 'object',
      returnValue: 'resultRows',
    });
    return {
      rows: normalizeRows(rows),
      changes: changesOf(database, statement.sql),
      lastInsertRowId: this.#lastInsertRowId(database),
    };
  }

  #lastInsertRowId(database: Database): bigint {
    if (!this.#sqlite3 || database.pointer === undefined) return 0n;
    return this.#sqlite3.capi.sqlite3_last_insert_rowid(database.pointer);
  }

  #requireDatabase(): Database {
    if (!this.#database) throw new DatabaseEngineError('engine-unavailable', '数据库尚未打开');
    return this.#database;
  }

  #toSqlError(error: unknown): DatabaseEngineError {
    if (error instanceof DatabaseEngineError) return error;
    return new DatabaseEngineError('sql-error', errorMessage(error));
  }

  async #restoreSnapshot(): Promise<void> {
    const store = this.#snapshotStore;
    const sqlite3 = this.#sqlite3;
    const database = this.#database;
    if (!store || !sqlite3 || !database) return;
    const snapshot = await store.load();
    if (!snapshot || snapshot.byteLength === 0) return;
    if (database.pointer === undefined) throw new DatabaseEngineError('engine-unavailable', 'SQLite 内存库句柄不可用');

    let pointer: WasmPointer | null = null;
    try {
      pointer = sqlite3.wasm.allocFromTypedArray(snapshot);
      const flags = sqlite3.capi.SQLITE_DESERIALIZE_FREEONCLOSE | sqlite3.capi.SQLITE_DESERIALIZE_RESIZEABLE;
      const resultCode = sqlite3.capi.sqlite3_deserialize(
        database.pointer,
        'main',
        pointer,
        snapshot.byteLength,
        snapshot.byteLength,
        flags,
      );
      pointer = null;
      if (resultCode !== sqlite3.capi.SQLITE_OK) {
        throw new Error(`sqlite3_deserialize 返回错误码 ${resultCode}`);
      }
    } catch (error) {
      if (pointer !== null) sqlite3.wasm.dealloc(pointer);
      this.#snapshotWarning = `IndexedDB SQLite 快照损坏，已使用内存副本：${errorMessage(error)}`;
    }
  }

  async #saveSnapshot(): Promise<void> {
    const store = this.#snapshotStore;
    if (!store || !this.#database) return;
    try {
      await store.save(this.exportDatabase());
    } catch (error) {
      this.#snapshotWarning = `IndexedDB SQLite 快照写入失败：${errorMessage(error)}`;
    }
  }
}